function closeModal(){$('#modalBackdrop').classList.add('hidden');activeTab=null}
function showTab(tab){const body=$('#modalBody');body.innerHTML=content(tab);bindModal(tab)}
function cards(list,empty){return list?.length?`<div class="drawer-grid">${list.map(x=>`<button class="data-card item-card" data-item="${esc(x.id)}">${grade(x.grade)}<strong>${esc(x.name||x.title||'항목')}</strong><small>${esc(x.description||x.role||'')}</small></button>`).join('')}</div>`:`<div class="empty-card">${empty}</div>`}
function people(){return `<div class="section-title"><div><small>CHARACTERS</small><h3>기억 속 인물</h3></div><button class="primary compact" id="addCharacter">+ 인물 추가</button></div>${state.characters.length?`<div class="character-grid">${state.characters.map(c=>`<article class="character-card"><button class="portrait-button" data-photo="${esc(c.id)}">${c.portrait?`<img src="${esc(c.portrait)}" alt="${esc(c.name)}">`:'<span>프로필 사진 설정</span>'}</button><strong>${esc(c.name)}</strong><p>${esc(c.introduction||'소개 없음')}</p><button data-memory="${esc(c.id)}">장기기억 확인·수정</button></article>`).join('')}</div>`:'<div class="empty-card">등록된 인물이 없습니다.</div>'}`}
function equipment(){return `<section><div class="section-title"><div><small>EQUIPPED</small><h3>착용 장비</h3></div>${gradeLegend()}</div><div class="slot-grid">${SLOTS.map(s=>{const it=state.equipped?.[s];return `<button class="slot ${it?'filled':''}" data-slot="${s}"><small>${s}</small><strong>${it?esc(it.name):'비어 있음'}</strong>${it?grade(it.grade):''}</button>`}).join('')}</div></section><section class="lower-section"><div class="section-title"><div><small>INVENTORY</small><h3>보유 장비</h3></div></div>${cards(state.equipment,'보유 장비가 없습니다.')}</section>`}
function essence(){const open=essenceSlotsFor(state.player.level),equipped=state.equippedEssences||[];return `<section><div class="section-title"><div><small>ESSENCE SLOTS</small><h3>장착 정수 <em>${equipped.length} / ${open}</em></h3></div>${gradeLegend()}</div><div class="essence-slots">${Array.from({length:15},(_,i)=>{const it=equipped[i],locked=i>=open;return `<button class="essence-slot ${locked?'locked':it?'filled':''}" ${locked?'disabled':''} data-essence-slot="${i}"><span>${locked?'🔒':i+1}</span><strong>${locked?'Lv.'+(i*3+1):it?esc(it.name):'빈 슬롯'}</strong>${it?grade(it.grade):''}</button>`}).join('')}</div></section><section class="lower-section"><div class="section-title"><div><small>OWNED ESSENCES</small><h3>보유 정수</h3></div></div>${cards(state.essences,'보유 정수가 없습니다.')}</section>`}
function trait(){const t=state.player.trait||{};return `<article class="trait-panel"><small>HUMAN GROWTH</small><h2>${esc(t.title||'아직 개화하지 않음')}</h2><p>${esc(t.description||'인간족 고유의 가능성이 아직 모습을 드러내지 않았습니다.')}</p><div class="mastery"><span>특성 숙련도</span><b>${Number(t.mastery)||0}${Number(t.maxMastery)>0?` / ${Number(t.maxMastery)}`:''}</b></div><small class="readonly">게임 진행에 따라 CHRONICLE만 갱신할 수 있습니다.</small></article>`}
function derivedSkills(){const essences=state.equippedEssences||[],active=essences.flatMap(e=>e.activeSkills||e.active||[]),passive=essences.flatMap(e=>e.passiveSkills||e.passive||[]);for(const bonus of activeSetBonuses())passive.push(...(bonus.passiveSkills||bonus.skills||[]).map(s=>typeof s==='string'?{name:s,description:`${bonus.setName} 세트 효과`}:{...s,source:s.source||`${bonus.setName} 세트`}));return{active,passive}}
function skills(){const{active,passive}=derivedSkills(),list=(a,empty,kind)=>a.length?`<div class="skill-list">${a.map((s,i)=>{const x=typeof s==='string'?{name:s}:s;return `<button class="skill-card" data-skill="${i}" data-skill-kind="${kind}"><strong>${esc(x.name||x.title||'스킬')}</strong><small>${esc(x.description||'')}</small></button>`}).join('')}</div>`:`<div class="empty-card">${empty}</div>`;return `<div class="skill-columns"><section><div class="section-title"><div><small>ACTIVE</small><h3>액티브 스킬</h3></div></div>${list(active,'장착 정수에서 얻은 액티브 스킬이 없습니다.','active')}</section><section><div class="section-title"><div><small>PASSIVE</small><h3>패시브 스킬</h3></div></div>${list(passive,'장착 정수와 장비 세트에서 얻은 패시브 스킬이 없습니다.','passive')}</section></div>`}
function statTotals(){const base={...BASE_STATS,...state.player.stats},gear={},essenceBonus={},setBonus={},special={...SPECIAL_DEFAULTS,...state.player.specialStats},specialGear={},specialEssence={},specialSet={};for(const it of Object.values(state.equipped||{})){for(const[k,v]of Object.entries(it?.stats||{}))gear[k]=(gear[k]||0)+(Number(v)||0);for(const[k,v]of Object.entries(it?.specialStats||{}))specialGear[k]=(specialGear[k]||0)+(Number(v)||0)}for(const it of state.equippedEssences||[]){for(const[k,v]of Object.entries(it?.stats||{}))essenceBonus[k]=(essenceBonus[k]||0)+(Number(v)||0);for(const[k,v]of Object.entries(it?.specialStats||{}))specialEssence[k]=(specialEssence[k]||0)+(Number(v)||0)}for(const bonus of activeSetBonuses()){for(const[k,v]of Object.entries(bonus.stats||{}))setBonus[k]=(setBonus[k]||0)+(Number(v)||0);for(const[k,v]of Object.entries(bonus.specialStats||{}))specialSet[k]=(specialSet[k]||0)+(Number(v)||0)}const final={},specialFinal={};for(const k of Object.keys(STAT_INFO))final[k]=(base[k]||0)+(gear[k]||0)+(essenceBonus[k]||0)+(setBonus[k]||0);for(const k of Object.keys(SPECIAL_INFO))specialFinal[k]=(special[k]||0)+(specialGear[k]||0)+(specialEssence[k]||0)+(specialSet[k]||0);return{base,gear,essenceBonus,setBonus,final,special,specialGear,specialEssence,specialSet,specialFinal}}
function recalculateResources(){const p=state?.player;if(!p)return;const vitality=Math.max(0,Number(statTotals().final.vitality)||0),extra=Math.max(0,vitality-5),oldHpMax=Math.max(1,Number(p.maxHp)||100),oldSpMax=Math.max(1,Number(p.maxSp)||100);if(!p.resourceFormula)p.resourceFormula={baseHp:Math.max(1,oldHpMax-extra*5),baseSp:Math.max(1,oldSpMax-extra*3),hpPerVitality:5,spPerVitality:3};const f=p.resourceFormula,nextHp=Math.max(1,Math.round((Number(f.baseHp)||100)+extra*(Number(f.hpPerVitality)||5))),nextSp=Math.max(1,Math.round((Number(f.baseSp)||100)+extra*(Number(f.spPerVitality)||3)));if(nextHp!==oldHpMax)p.hp=Math.max(0,Math.min(nextHp,Math.round((Number(p.hp)||0)/oldHpMax*nextHp)));if(nextSp!==oldSpMax)p.sp=Math.max(0,Math.min(nextSp,Math.round((Number(p.sp)||0)/oldSpMax*nextSp)));p.maxHp=nextHp;p.maxSp=nextSp}
function stats(){const t=statTotals(),initial=state.player.initialStats||{},level=state.player.statGrowth?.level||{},chronicle=state.player.statGrowth?.chronicle||{},sections=state.settings.statSections||{base:true,special:true},baseRows=Object.entries(STAT_INFO).map(([k,x])=>{const bonus=(t.gear[k]||0)+(t.essenceBonus[k]||0)+(t.setBonus[k]||0);return `<article class="stat-row"><div><strong>${x[0]}</strong><small>${x[1]}</small></div><span>초기 ${initial[k]??BASE_STATS[k]??0}</span><span>레벨 +${level[k]||0}</span><span>진행 +${chronicle[k]||0}</span><span>장비·정수·세트 ${bonus>=0?'+':''}${bonus}</span><b>${t.final[k]||0}</b></article>`}).join(''),specialRows=Object.entries(SPECIAL_INFO).map(([k,x])=>{const bonus=(t.specialGear[k]||0)+(t.specialEssence[k]||0)+(t.specialSet[k]||0);return `<article class="special-stat-row"><div><strong>${x[0]}</strong><small>${x[1]}</small></div><span>기본 ${t.special[k]||0}%</span><span>장비·정수·세트 ${bonus>=0?'+':''}${bonus}%</span><b>${t.specialFinal[k]||0}%</b></article>`}).join('');return `<div class="stat-screen"><p class="stat-note">확정 스탯은 생성·레벨 성장·CHRONICLE 진행이 누적되며 장비·정수·세트 보정이 더해집니다.</p><section class="stat-section"><button class="stat-section-toggle" data-stat-section="base"><span>기본 스탯</span><i>${sections.base?'−':'＋'}</i></button><div class="stat-section-body ${sections.base?'':'hidden'}">${baseRows}</div></section><section class="stat-section"><button class="stat-section-toggle" data-stat-section="special"><span>특수 스탯</span><i>${sections.special?'−':'＋'}</i></button><div class="stat-section-body ${sections.special?'':'hidden'}">${specialRows}</div></section></div>`}
function inventory(){return state.inventory.length?`<div class="drawer-grid">${state.inventory.map(x=>`<button class="data-card inventory-card" data-inventory="${esc(x.id)}">${grade(x.grade)}<strong>${esc(x.name)}</strong><small>${esc(x.type)} · ${Number(x.quantity)||1}개</small><p>${esc(x.description||'설명 없음')}</p></button>`).join('')}</div>`:'<div class="empty-card">소지품이 없습니다.</div>'}
function ruleReminderDue(){const r=state.settings.ruleReminder||{},byCommands=(Number(r.commandCount)||0)-(Number(r.lastCommandCount)||0)>=Math.max(10,Number(r.minimumCommands)||30),byTime=Date.now()-(Number(r.lastAt)||0)>=Math.max(86400000,Number(r.minIntervalMs)||604800000);return byCommands&&byTime}
function buildRuleReminder(){const gm=state.settings.gmRules?.trim(),sheet=state.settings.sheetRules?.trim();if(!gm&&!sheet)return'';return `CHRONICLE 진행 규칙을 다시 확인해 주세요. 아래 규칙은 요약하거나 임의로 변경하지 말고 이후 진행에 적용합니다.\n\n[GM 진행 규칙]\n${gm||'저장된 규칙 없음'}\n\n[Google Sheets 연결 규칙]\n${sheet||'저장된 규칙 없음'}`}
function consumeRuleReminder(force=false){if(!force&&!ruleReminderDue())return null;const prompt=buildRuleReminder();if(!prompt)return null;const r=state.settings.ruleReminder;r.lastAt=Date.now();r.lastCommandCount=Number(r.commandCount)||0;save(false);return prompt}
function content(tab){if(tab==='people')return people();if(tab==='equipment')return equipment();if(tab==='essence')return essence();if(tab==='stats')return stats();if(tab==='trait')return trait();if(tab==='skills')return skills();if(tab==='inventory')return inventory();if(tab==='settings'){const sync=state.settings.sheetSync||{};return `<div class="settings-stack"><section class="setting-card mobile-game-test"><strong>게임 상태 테스트</strong><small>캐릭터 상태와 테스트 아이템을 직접 조정합니다.</small><button class="primary" id="openGameStateTest">게임 상태 테스트 열기</button></section><label class="setting-card"><strong>ChatGPT 채팅방 링크</strong><small>추후 CHRONICLE 버튼에서 ChatGPT를 사이드로 실행할 때 사용합니다.</small><input id="chatgptUrl" type="url" placeholder="https://chatgpt.com/..." value="${esc(state.settings?.chatgptUrl||'')}"><button class="primary" id="saveChatgptUrl">링크 저장</button></label><label class="setting-card"><strong>이미지 생성용 GPT 링크</strong><small>프로필 이미지 프롬프트를 복사한 뒤 자동으로 이동할 GPT 주소입니다.</small><input id="imageGptUrl" type="url" placeholder="https://chatgpt.com/g/..." value="${esc(state.settings?.imageGptUrl||'')}"><button class="primary" id="saveImageGptUrl">이미지 GPT 링크 저장</button></label><section class="setting-card rule-settings"><strong>GM 규칙 상기</strong><small>규칙은 저장만 해두고 최소 30개의 상태 명령과 7일이 모두 지난 경우에만 자동 연동 API가 상기하도록 설계되어 있습니다.</small><label>GM 진행 규칙<textarea id="gmRules" rows="7" placeholder="GM의 진행 원칙과 세계관 규칙">${esc(state.settings.gmRules||'')}</textarea></label><label>Google Sheets 연결 규칙<textarea id="sheetRules" rows="7" placeholder="시트 명령 작성과 동기화 규칙">${esc(state.settings.sheetRules||'')}</textarea></label><button class="primary" id="saveRulePrompts">규칙 저장</button><button class="secondary-rule" id="copyRuleReminder">지금 상기 프롬프트 복사</button><small>${ruleReminderDue()?'간헐적 상기 조건 충족':'상기 대기 중 · 잦은 반복 방지 적용'}</small></section><article class="setting-card sync-card"><strong>Google Sheets 명령 중계</strong><small>TRPG_COMMANDS 탭의 새 명령을 4초마다 확인해 현재 캐릭터에 반영합니다.</small><a href="https://docs.google.com/spreadsheets/d/${SHEET_SYNC.sheetId}/edit" target="_blank" rel="noopener">연결된 시트 열기</a><div><span>상태</span><b id="sheetSyncStatus">${esc(sync.lastResult||'연결 대기 중')}</b></div><button class="primary" id="syncSheetNow">지금 동기화</button></article></div>`}return '<div class="empty-card">현재 위치, 지역 정보와 지도 표시 옵션 영역입니다.</div>'}
function setData(item){if(!item?.set&&!item?.setId)return null;const raw=item.set||{};return{id:raw.id||item.setId,name:raw.name||item.setName||'이름 없는 세트',description:raw.description||item.setDescription||'',bonuses:raw.bonuses||item.setBonuses||[]}}
function equippedSetState(){const groups={};for(const [slot,item] of Object.entries(state.equipped||{})){const set=setData(item);if(!set?.id)continue;groups[set.id]??={set,count:0,slots:new Set(),items:[]};if(!groups[set.id].slots.has(slot)){groups[set.id].slots.add(slot);groups[set.id].count++;groups[set.id].items.push(item)}}return Object.values(groups)}
function activeSetBonuses(){return equippedSetState().flatMap(g=>(g.set.bonuses||[]).filter(b=>g.count>=Number(b.required||b.pieces||0)).map(b=>({...b,setId:g.set.id,setName:g.set.name,equipped:g.count})))}
function setPanel(item){const set=setData(item);if(!set)return'';const equipped=equippedSetState().find(x=>x.set.id===set.id)?.count||0;return `<section class="set-panel"><small>EQUIPMENT SET</small><h3>${esc(set.name)} <span>${equipped}개 장착</span></h3>${set.description?`<p>${esc(set.description)}</p>`:''}<div>${(set.bonuses||[]).map(b=>`<article class="${equipped>=Number(b.required||b.pieces||0)?'active':''}"><b>${Number(b.required||b.pieces||0)}세트</b><span>${esc(b.description||[...Object.entries(b.stats||{}).map(([k,v])=>`${STAT_INFO[k]?.[0]||k} ${v>=0?'+':''}${v}`),...Object.entries(b.specialStats||{}).map(([k,v])=>`${SPECIAL_INFO[k]?.[0]||k} ${v>=0?'+':''}${v}%`)].join(' · ')||'특수 효과')}</span></article>`).join('')}</div></section>`}
function detail(item,actions=''){const skills=(type,label)=>(item[type]||[]).length?`<div><b>${label}</b><p>${(item[type]||[]).map(x=>esc(typeof x==='string'?x:x.name||x.title)).join(', ')}</p></div>`:'';$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 목록</button><article class="detail-card">${grade(item.grade)}<h2>${esc(item.name)}</h2><p>${esc(item.description||'설명 없음')}</p><div class="stat-list">${statsText(item.stats)}</div>${skills('activeSkills','액티브')}${skills('passiveSkills','패시브')}${setPanel(item)}<div class="actions">${actions}</div></article>`;$('#detailBack').onclick=()=>showTab(activeTab)}
function compare(next,current,confirmLabel){const keys=[...new Set([...Object.keys(current?.stats||{}),...Object.keys(next?.stats||{})])];return `<div class="compare"><div><small>현재</small><b>${esc(current?.name||'없음')}</b></div><span>→</span><div><small>변경</small><b>${esc(next.name)}</b></div></div><div class="stat-list">${keys.map(k=>`<span>${esc(k)}</span><b>${current?.stats?.[k]??0} → ${next.stats?.[k]??0}</b>`).join('')}</div><button class="primary" id="confirmMove">${confirmLabel}</button>`}
function equip(item,slot){const current=state.equipped[slot];$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 취소</button><h3>${esc(slot)} 장착 확인</h3>${compare(item,current,'장착 확정')}`;$('#detailBack').onclick=()=>showTab('equipment');$('#confirmMove').onclick=()=>{state.equipment=state.equipment.filter(x=>x.id!==item.id);if(current)state.equipment.push(current);state.equipped[slot]=item;save()}}
function sheetWriterConfig(){try{return{...JSON.parse(localStorage.getItem(SHEET_WRITER_KEY)||'{}'),sheetWriteUrl:state.settings.sheetWriteUrl||JSON.parse(localStorage.getItem(SHEET_WRITER_KEY)||'{}').sheetWriteUrl||'',sheetWriteToken:state.settings.sheetWriteToken||JSON.parse(localStorage.getItem(SHEET_WRITER_KEY)||'{}').sheetWriteToken||''}}catch{return{sheetWriteUrl:state.settings.sheetWriteUrl||'',sheetWriteToken:state.settings.sheetWriteToken||''}}}
function saveSheetWriterConfig(config){localStorage.setItem(SHEET_WRITER_KEY,JSON.stringify(config));state.settings.sheetWriteUrl=config.sheetWriteUrl;state.settings.sheetWriteToken=config.sheetWriteToken}
function mountSheetWriterSettings(){const syncCard=document.querySelector('.sync-card'),config=sheetWriterConfig();if(!syncCard)return;syncCard.insertAdjacentHTML('beforebegin',`<section class="setting-card sheet-writer-card"><strong>시트 명령 연결</strong><small>Apps Script를 통해 비공개 시트의 명령을 읽고 처리 상태까지 기록합니다. 캐릭터 생성·삭제 연결에도 함께 사용됩니다.</small><label>Apps Script 웹 앱 주소<input id="sheetWriteUrl" type="url" placeholder="https://script.google.com/macros/s/.../exec" value="${esc(config.sheetWriteUrl||'')}"></label><label>연결 보안 토큰<input id="sheetWriteToken" type="password" autocomplete="off" value="${esc(config.sheetWriteToken||'')}"></label><div><span>현재 캐릭터 ID</span><code>${esc(activeSaveId||'캐릭터 미선택')}</code></div><button class="primary" id="saveSheetWriter">시트 연결 저장</button><small>${pendingSheetDeletions().length?`삭제 재시도 대기 ${pendingSheetDeletions().length}건`:'삭제 대기 없음'}</small></section>`)}
function bindModal(tab){if(tab==='people')bindPeople();if(tab==='equipment')bindEquipment();if(tab==='essence')bindEssence();if(tab==='stats')document.querySelectorAll('[data-stat-section]').forEach(b=>b.onclick=()=>{const k=b.dataset.statSection;state.settings.statSections[k]=!state.settings.statSections[k];save(false);showTab('stats')});if(tab==='skills')document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{const lists=derivedSkills(),list=b.dataset.skillKind==='active'?lists.active:lists.passive,raw=list[Number(b.dataset.skill)],item=typeof raw==='string'?{name:raw}:raw;detail({...item,name:item?.name||item?.title||'스킬',grade:item?.grade||'일반',stats:item?.stats||{}})});if(tab==='settings'){mountSheetWriterSettings();$('#openGameStateTest').onclick=()=>{closeModal();openGameStateTest()};const storeUrl=(input,key,message)=>{const v=$(input).value.trim();if(v){try{const u=new URL(v);if(!['http:','https:'].includes(u.protocol))throw 0}catch{return alert('올바른 http/https 링크를 입력해 주세요.')}}state.settings[key]=v;save(false);alert(message)};$('#saveChatgptUrl').onclick=()=>storeUrl('#chatgptUrl','chatgptUrl','ChatGPT 채팅방 링크를 저장했습니다.');$('#saveImageGptUrl').onclick=()=>storeUrl('#imageGptUrl','imageGptUrl','이미지 GPT 링크 저장');$('#saveSheetWriter').onclick=()=>{const url=$('#sheetWriteUrl').value.trim(),token=$('#sheetWriteToken').value.trim();if(url){try{new URL(url)}catch{return alert('올바른 Apps Script 웹 앱 주소를 입력해 주세요.')}}state.settings.sheetWriteUrl=url;state.settings.sheetWriteToken=token;save(false);retryPendingSheetDeletions();alert('시트 삭제 연결을 저장했습니다.')};$('#saveRulePrompts').onclick=()=>{state.settings.gmRules=$('#gmRules').value.trim();state.settings.sheetRules=$('#sheetRules').value.trim();save(false);alert('GM 규칙과 시트 연결 규칙을 저장했습니다.')};$('#copyRuleReminder').onclick=()=>{state.settings.gmRules=$('#gmRules').value.trim();state.settings.sheetRules=$('#sheetRules').value.trim();const prompt=consumeRuleReminder(true);if(!prompt)return alert('먼저 상기할 규칙을 입력해 주세요.');copyText(prompt).then(ok=>alert(ok?'규칙 상기 프롬프트를 복사했습니다.':'클립보드 복사에 실패했습니다.'))};$('#syncSheetNow').onclick=()=>syncSheetCommands(true)}if(tab==='inventory')document.querySelectorAll('[data-inventory]').forEach(b=>b.onclick=()=>showInventoryDetail(b.dataset.inventory))}
function isLootContainer(item={}){return item.container===true||item.lootContainer===true||/상자|보물함|궤짝|chest|loot.?box|treasure.?box/i.test(`${item.type||''} ${item.name||''}`)}
function showInventoryDetail(id){const item=state.inventory.find(x=>x.id===id);if(!item)return showTab('inventory');const container=isLootContainer(item),action=container?'<button class="primary" id="openInventoryContainer">상자 열기</button>':item.usable?'<button class="primary" id="useInventoryItem">사용</button>':'<small class="readonly">현재 직접 사용할 수 없는 소지품입니다.</small>';$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 소지품 목록</button><article class="detail-card inventory-detail">${grade(item.grade)}<h2>${esc(item.name)}</h2><div class="item-meta"><span>${esc(item.type)}</span><b>${Number(item.quantity)||1}개</b></div><p>${esc(item.description||'설명 없음')}</p>${item.effect?`<div class="item-effect">✦ ${esc(item.effect)}</div>`:''}${action}</article>`;$('#detailBack').onclick=()=>showTab('inventory');$('#useInventoryItem')?.addEventListener('click',()=>{const result=window.TRPGWindow.useInventoryItem(item.id);if(result.ok)showTab('inventory')});$('#openInventoryContainer')?.addEventListener('click',()=>openInventoryContainer(item.id))}
function grantPayload(payload={},type=''){if(!payload||typeof payload!=='object')return{};const keys=type==='grant_equipment'?['item','equipment','reward','data']:type==='grant_essence'?['item','essence','reward','data']:['item','inventory','reward','data'];const nested=keys.map(key=>payload[key]).find(value=>value&&typeof value==='object'&&!Array.isArray(value));return nested?{...nested,quantity:payload.quantity??nested.quantity}:payload}
function lootCommandLabel(command){const type=String(command.command_type||command.type||'').toLowerCase(),raw=command.payload_json??command.payload??{},payload=grantPayload(raw,type);if(type==='grant_equipment')return`장비 · ${payload.name||payload.title||'이름 없는 장비'}`;if(type==='grant_essence')return`정수 · ${payload.name||payload.title||'이름 없는 정수'}`;if(type==='grant_inventory')return`${isEquipmentPayload(payload)?'장비':'소지품'} · ${payload.name||payload.title||'이름 없는 물품'}${payload.quantity>1?` ×${payload.quantity}`:''}`;if(type==='award_experience')return`경험치 +${Number(raw.amount??raw.exp)||0}`;if(type==='grant_gold')return`골드 +${Number(raw.amount??raw.gold)||0} G`;return''}
async function openInventoryContainer(id){const item=state.inventory.find(entry=>entry.id===id),button=$('#openInventoryContainer');if(!item||!isLootContainer(item)||!button)return;const snapshot=clone(state);button.disabled=true;button.textContent='봉인을 해제하는 중…';try{const result=await sheetCommandRequest('openContainer',{activeSaveId,item:clone(item),gameState:geminiStateSnapshot(),gmRules:state.settings.gmRules||''}),allowed=new Set(['grant_equipment','grant_essence','grant_inventory','award_experience','grant_gold']),commands=(Array.isArray(result.commands)?result.commands:[]).filter(command=>allowed.has(String(command.command_type||command.type||'').toLowerCase()));if(!commands.length)throw new Error('상자에서 획득할 보상이 생성되지 않았습니다.');for(const command of commands)applySheetCommand({command_type:command.command_type||command.type,payload_json:command.payload_json??command.payload??{}});const opened=state.inventory.find(entry=>entry.id===id);if(opened){opened.quantity=(Number(opened.quantity)||1)-1;if(opened.quantity<=0)state.inventory=state.inventory.filter(entry=>entry.id!==id)}save(false);const rewards=commands.map(lootCommandLabel).filter(Boolean),message=(Array.isArray(result.messages)?result.messages:[]).map(entry=>entry.text||entry.action||'').filter(Boolean).join(' ');$('#modalBody').innerHTML=`<section class="loot-reveal"><small>LOOT ACQUIRED</small><h2>${esc(item.name)} 개봉</h2><div class="loot-rune">✦</div>${message?`<p>${esc(message)}</p>`:''}<div class="loot-list">${rewards.map(reward=>`<article>◆ ${esc(reward)}</article>`).join('')}</div><button class="primary" id="lootConfirm">확인</button></section>`;$('#lootConfirm').onclick=()=>showTab('inventory')}catch(error){state=snapshot;save(false);showInventoryDetail(id);const card=$('#modalBody .inventory-detail');card?.insertAdjacentHTML('beforeend',`<small class="loot-error">✦ ${esc(error?.message||'상자를 열지 못했습니다.')}</small>`)}}
function bindPeople(){$('#addCharacter').onclick=()=>{$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 취소</button><form id="characterForm" class="form-card"><label>이름<input name="name" required></label><label>간단 소개<textarea name="introduction" rows="3"></textarea></label><label>고정 외형 특성<textarea name="appearance" rows="4" placeholder="머리색, 눈동자, 인상, 체형, 흉터, 복장 등"></textarea></label><label>장기기억<textarea name="longMemory" rows="7"></textarea></label><button class="primary">추가</button></form>`;$('#detailBack').onclick=()=>showTab('people');$('#characterForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);state.characters.push({id:uid('character'),name:f.get('name').trim(),introduction:f.get('introduction').trim(),appearance:f.get('appearance').trim(),longMemory:f.get('longMemory').trim(),portrait:'',updatedAt:Date.now(),source:'user'});save()}};document.querySelectorAll('[data-memory]').forEach(b=>b.onclick=()=>{const c=state.characters.find(x=>x.id===b.dataset.memory);$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 목록</button><form id="memoryForm" class="form-card"><h3>${esc(c.name)} · 장기기억</h3><textarea name="memory" rows="12">${esc(c.longMemory||'')}</textarea><button class="primary">저장</button></form>`;$('#detailBack').onclick=()=>showTab('people');$('#memoryForm').onsubmit=e=>{e.preventDefault();c.longMemory=new FormData(e.currentTarget).get('memory').trim();c.updatedAt=Date.now();save()}});document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>openPortraitSetup('character',b.dataset.photo))}
function portraitSubject(kind,id){if(kind==='player')return state.player;return state.characters.find(c=>c.id===id)}
function portraitAppearance(kind,subject){if(kind==='player')return subject.appearance||subject.character?.appearance||'';return subject.appearance||''}
function portraitPrompt(kind,subject,appearance){const role=kind==='player'?'플레이어 캐릭터':'등장인물';return `중세 판타지 TRPG의 ${role} 프로필 초상화를 제작해 주세요.\n\n인물 이름: ${subject.name||'이름 없음'}\n고정 외형 특성: ${appearance||'아직 구체적으로 정해지지 않음'}\n보조 정보: ${subject.introduction||subject.title||''}\n\n표현 지침:\n- 낡고 은은한 양피지 배경\n- 고전 중세 판타지 삽화와 사실적인 회화가 섞인 분위기\n- 얼굴과 상반신 중심의 정면 또는 살짝 비스듬한 구도\n- 외형 특성을 빠뜨리거나 임의로 변경하지 말 것\n- 차분한 갈색·금색 계열, 섬세한 잉크선과 부드러운 명암\n- 글자, 문장, 로고, 테두리는 이미지에 넣지 말 것\n- 정사각형 1:1 비율, 원형 프로필로 잘라도 얼굴이 온전히 남는 여백`}
async function copyText(text){try{await navigator.clipboard.writeText(text);return true}catch{const box=document.createElement('textarea');box.value=text;box.style.position='fixed';box.style.opacity='0';document.body.append(box);box.select();const ok=document.execCommand('copy');box.remove();return ok}}
function openPortraitSetup(kind,id=''){const subject=portraitSubject(kind,id);if(!subject)return;activeTab=kind==='player'?'playerProfile':'people';$('#modalTitle').textContent=kind==='player'?'내 프로필':'인물 프로필';const appearance=portraitAppearance(kind,subject);$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← ${kind==='player'?'닫기':'인물 목록'}</button><section class="portrait-settings"><div class="portrait-preview">${subject.portrait?`<img src="${esc(subject.portrait)}" alt="${esc(subject.name)}">`:`<span>${esc((subject.name||'?')[0])}</span>`}</div><h2>${esc(subject.name||'이름 없음')}</h2><label>고정 외형 특성<textarea id="portraitAppearance" rows="5" placeholder="머리색, 눈동자, 인상, 체형, 흉터, 복장 등">${esc(appearance)}</textarea></label><div class="portrait-actions"><button id="generatePortraitPrompt">✦ 이미지 생성</button><button id="importPortrait">▣ 이미지 불러오기</button></div><small>이미지 생성은 프롬프트를 복사하고 설정된 이미지 생성용 GPT를 엽니다.</small><input id="portraitImportFile" type="file" accept="image/png,image/jpeg,image/webp" hidden></section>`;$('#detailBack').onclick=()=>kind==='player'?closeModal():showTab('people');const updateAppearance=()=>{const value=$('#portraitAppearance').value.trim();if(kind==='player'){subject.appearance=value;subject.character={...(subject.character||{}),appearance:value}}else subject.appearance=value;subject.updatedAt=Date.now();save(false);return value};$('#generatePortraitPrompt').onclick=()=>{const prompt=portraitPrompt(kind,subject,updateAppearance()),url=state.settings.imageGptUrl,opened=url?window.open(url,'_blank','noopener'):null;copyText(prompt).then(ok=>alert(ok?(url?'이미지 프롬프트를 복사하고 이미지 생성용 GPT를 열었습니다.':'이미지 프롬프트를 복사했습니다. 설정에서 이미지 생성용 GPT 링크를 저장해 주세요.'):'프롬프트 복사에 실패했습니다.'));if(url&&!opened)alert('팝업이 차단되었습니다. 설정에 저장된 링크를 직접 열어 주세요.')};const input=$('#portraitImportFile');$('#importPortrait').onclick=()=>input.click();input.onchange=()=>{const file=input.files?.[0];if(!file)return;updateAppearance();const reader=new FileReader();reader.onload=()=>cropPortrait(kind,id,String(reader.result));reader.readAsDataURL(file)}}
function cropPortrait(kind,id,src){$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 취소</button><div class="crop-wrap"><h3>프로필 사진 맞추기</h3><div class="crop-stage" id="cropStage"><img id="cropImage" src="${esc(src)}" alt=""><div class="crop-mask"></div></div><label>확대<input id="cropZoom" type="range" min="1" max="3" step=".01" value="1"></label><button class="primary" id="cropSave">이대로 저장</button></div>`;$('#detailBack').onclick=()=>openPortraitSetup(kind,id);const stage=$('#cropStage'),img=$('#cropImage'),zoom=$('#cropZoom');let scale=1,x=0,y=0,drag=false,sx=0,sy=0,bx=0,by=0;const draw=()=>img.style.transform=`translate(${x}px,${y}px) scale(${scale})`;zoom.oninput=()=>{scale=Number(zoom.value);draw()};stage.onpointerdown=e=>{drag=true;sx=e.clientX;sy=e.clientY;bx=x;by=y;stage.setPointerCapture(e.pointerId)};stage.onpointermove=e=>{if(drag){x=bx+e.clientX-sx;y=by+e.clientY-sy;draw()}};stage.onpointerup=stage.onpointercancel=()=>drag=false;$('#cropSave').onclick=()=>{const source=new Image();source.onload=()=>{const size=384,cv=document.createElement('canvas'),ctx=cv.getContext('2d');cv.width=cv.height=size;const base=Math.max(size/source.naturalWidth,size/source.naturalHeight)*scale,w=source.naturalWidth*base,h=source.naturalHeight*base,ratio=size/stage.clientWidth;ctx.drawImage(source,(size-w)/2+x*ratio,(size-h)/2+y*ratio,w,h);const subject=portraitSubject(kind,id);if(!subject)return;subject.portrait=cv.toDataURL('image/jpeg',.82);delete subject.portraitOriginal;subject.updatedAt=Date.now();try{save(false)}catch(error){delete subject.portrait;return alert('프로필 사진을 저장하지 못했습니다. 브라우저 저장 공간을 확인해 주세요.')}if(kind==='player')$('#playerAvatar').innerHTML=`<img src="${esc(subject.portrait)}" alt="${esc(subject.name)}">`;openPortraitSetup(kind,id)};source.onerror=()=>alert('이미지를 읽지 못했습니다. 다른 이미지 파일을 선택해 주세요.');source.src=src}}
function bindEquipment(){document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const item=state.equipment.find(x=>x.id===b.dataset.item);detail(item,`<button class="primary" id="equipOwned">장착</button>`);$('#equipOwned').onclick=()=>{$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 취소</button><h3>장착 부위 선택</h3><div class="slot-grid">${SLOTS.map(s=>`<button class="slot" data-pick-slot="${s}"><small>${s}</small><strong>${esc(state.equipped[s]?.name||'비어 있음')}</strong></button>`).join('')}</div>`;$('#detailBack').onclick=()=>showTab('equipment');document.querySelectorAll('[data-pick-slot]').forEach(x=>x.onclick=()=>equip(item,x.dataset.pickSlot))}});document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{const slot=b.dataset.slot,item=state.equipped[slot];if(!item)return;const canChange=state.equipment.length>0;detail(item,`${canChange?'<button class="primary equipment-action" id="changeEquip">변경</button>':''}<button class="unequip-button equipment-action" id="unequip">해제</button>`);$('#unequip').onclick=()=>{state.equipment.push(item);delete state.equipped[slot];save()};if(canChange)$('#changeEquip').onclick=()=>{$('#modalBody').innerHTML=`<button class="back-button" id="detailBack">← 취소</button><h3>${esc(slot)} 변경 장비 선택</h3>${cards(state.equipment,'변경할 장비가 없습니다.')}`;$('#detailBack').onclick=()=>showTab('equipment');document.querySelectorAll('[data-item]').forEach(x=>x.onclick=()=>equip(state.equipment.find(v=>v.id===x.dataset.item),slot))}})}
function bindEssence(){document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const item=state.essences.find(x=>x.id===b.dataset.item),hasRoom=state.equippedEssences.length<essenceSlotsFor(state.player.level);detail(item,hasRoom?'<button class="primary" id="equipEssence">빈 슬롯에 장착</button>':'<small>열린 빈 슬롯이 없습니다.</small>');const equipButton=$('#equipEssence');if(equipButton)equipButton.onclick=()=>{state.essences=state.essences.filter(x=>x.id!==item.id);state.equippedEssences.push(item);save()}});document.querySelectorAll('[data-essence-slot]').forEach(b=>b.onclick=()=>{const item=state.equippedEssences[Number(b.dataset.essenceSlot)];if(item)detail(item,'<small>장착한 정수는 UI에서 해제·교체·삭제할 수 없습니다.</small>')})}
