function pendingSheetDeletions(){try{return JSON.parse(localStorage.getItem(DELETE_QUEUE_KEY)||'[]')}catch{return[]}}
function writePendingSheetDeletions(items){localStorage.setItem(DELETE_QUEUE_KEY,JSON.stringify(items.slice(-100)))}
function queueSheetDeletion(characterId,characterName){const list=pendingSheetDeletions();if(!list.some(x=>x.characterId===characterId))list.push({characterId,characterName,queuedAt:Date.now(),attempts:0});writePendingSheetDeletions(list)}
function pendingCharacterRegistrations(){try{return JSON.parse(localStorage.getItem(REGISTER_QUEUE_KEY)||'[]')}catch{return[]}}
function writePendingCharacterRegistrations(items){localStorage.setItem(REGISTER_QUEUE_KEY,JSON.stringify(items.slice(-100)))}
function characterRegistration(characterId,snapshot=state){return{characterId,name:snapshot.player?.name||'이름 없음',level:Number(snapshot.player?.level)||1,title:snapshot.player?.title||'모험가',createdAt:snapshot.player?.character?.createdAt||new Date().toISOString(),profile:{character:snapshot.player?.character||{},stats:snapshot.player?.stats||{},specialStats:snapshot.player?.specialStats||{},trait:snapshot.player?.trait||{},location:snapshot.location||'',gold:Number(snapshot.gold)||0}}}
function queueCharacterRegistration(characterId,snapshot=state){const list=pendingCharacterRegistrations().filter(x=>x.characterId!==characterId);list.push({...characterRegistration(characterId,snapshot),queuedAt:Date.now(),attempts:0});writePendingCharacterRegistrations(list)}
async function sheetDeleteRequest(action,characterId,settings=sheetWriterConfig()){const url=settings?.sheetWriteUrl?.trim(),token=settings?.sheetWriteToken?.trim();if(!url||!token)throw new Error('시트 삭제 연결이 설정되지 않았습니다.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,token,spreadsheetId:SHEET_SYNC.sheetId,sheetName:SHEET_SYNC.sheetName,characterId}),signal:controller.signal});if(!response.ok)throw new Error(`시트 응답 오류 ${response.status}`);const result=await response.json();if(!result.ok)throw new Error(result.error||'시트 삭제 요청 실패');return result}finally{clearTimeout(timer)}}
async function sheetRegisterRequest(registration,settings=sheetWriterConfig()){const url=settings?.sheetWriteUrl?.trim(),token=settings?.sheetWriteToken?.trim();if(!url||!token)throw new Error('시트 쓰기 연결이 설정되지 않았습니다.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'upsertCharacter',token,spreadsheetId:SHEET_SYNC.sheetId,sheetName:'TRPG_CHARACTERS',...registration}),signal:controller.signal});if(!response.ok)throw new Error(`시트 응답 오류 ${response.status}`);const result=await response.json();if(!result.ok)throw new Error(result.error||'캐릭터 등록 실패');return result}finally{clearTimeout(timer)}}
async function retryPendingSheetDeletions(){const config=sheetWriterConfig();if(!config.sheetWriteUrl||!config.sheetWriteToken)return;const queue=pendingSheetDeletions(),remaining=[];for(const item of queue)try{await sheetDeleteRequest('deleteCharacterCommands',item.characterId,config)}catch{remaining.push({...item,attempts:(item.attempts||0)+1,lastAttemptAt:Date.now()})}writePendingSheetDeletions(remaining)}
async function retryPendingCharacterRegistrations(){const config=sheetWriterConfig();if(!config.sheetWriteUrl||!config.sheetWriteToken)return;const queue=pendingCharacterRegistrations(),remaining=[];for(const item of queue)try{await sheetRegisterRequest(item,config)}catch{remaining.push({...item,attempts:(item.attempts||0)+1,lastAttemptAt:Date.now()})}writePendingCharacterRegistrations(remaining)}
async function deleteCharacterSave(id,item){const name=item?.player?.name||'이름 없음',globalConfig=sheetWriterConfig(),settings=item?.settings?.sheetWriteUrl?item.settings:globalConfig;let count=null,connected=!!(settings?.sheetWriteUrl&&settings?.sheetWriteToken);if(connected)try{count=(await sheetDeleteRequest('previewCharacterCommands',id,settings)).count}catch{connected=false}const sheetText=count==null?'시트 연결이 없어 관련 정보 삭제는 재시도 대기열에 보관됩니다.':`Google Sheet의 관련 정보 ${count}개도 함께 삭제됩니다.`;if(!confirm(`'${name}' 캐릭터를 삭제할까요?\n\n${sheetText}\n다른 캐릭터와 공용 명령은 유지됩니다.`))return;writePendingCharacterRegistrations(pendingCharacterRegistrations().filter(x=>x.characterId!==id));if(connected)try{await sheetDeleteRequest('deleteCharacterCommands',id,settings)}catch{queueSheetDeletion(id,name)}else queueSheetDeletion(id,name);const saves=allSaves();delete saves[id];writeSaves(saves);if(activeSaveId===id){activeSaveId='';localStorage.removeItem(ACTIVE_KEY);state=clone(defaults)}showContinue()}
function showContinue(){const saves=allSaves(),rows=Object.entries(saves).sort((a,b)=>(b[1]._savedAt||0)-(a[1]._savedAt||0));homeOverlay(`<section class="home-screen continue-screen"><button class="home-back" id="homeBack">← 홈</button><small>SAVED CHRONICLES</small><h2>이어할 캐릭터 선택</h2><div class="save-list">${rows.map(([id,s])=>`<article><button data-load-save="${esc(id)}"><b>${esc(s.player?.name||'이름 없음')}</b><span>Lv.${s.player?.level||1} · ${esc(s.player?.title||'모험가')}</span><small>${esc(s.location||'장소 미정')}</small></button><button class="save-delete" data-delete-save="${esc(id)}">삭제</button></article>`).join('')}</div></section>`);$('#homeBack').onclick=showHome;document.querySelectorAll('[data-load-save]').forEach(b=>b.onclick=()=>{activeSaveId=b.dataset.loadSave;localStorage.setItem(ACTIVE_KEY,activeSaveId);state=merge(clone(defaults),allSaves()[activeSaveId]);$('#homeOverlay').remove();render()});document.querySelectorAll('[data-delete-save]').forEach(b=>b.onclick=()=>deleteCharacterSave(b.dataset.deleteSave,allSaves()[b.dataset.deleteSave]))}
function pointsLeft(d){return 12-STAT_KEYS.reduce((n,k)=>n+(Number(d.statAlloc[k]||5)-5),0)}
function creator(step,d){const progress=`<div class="creator-progress"><small>CHARACTER CREATION</small><span>${step+1} / 4</span></div>`,nav=(back,next,label='다음 ›')=>`<div class="creator-nav"><button id="creatorBack">${back}</button><button class="primary" id="creatorNext" ${next?'':'disabled'}>${label}</button></div>`;let body='';if(step===0)body=`${progress}<h2>누구의 연대기를 시작할까요?</h2><div class="selected-race"><small>PLAYER RACE</small><b>인간</b><p>종족 능력치 보정 없이 어떤 성장 방향에도 제약이 없습니다. 인간족은 진행에 따라 고유 특성이 개화합니다.</p></div><label>이름<input id="ccName" value="${esc(d.name)}" placeholder="캐릭터 이름"></label>${nav('‹ 홈',!!d.name.trim())}`;if(step===1)body=`${progress}<h2>어떤 모습으로 살아가나요?</h2><div class="form-grid"><label>성별<select id="ccSex"><option>남성</option><option>여성</option><option>직접 작성</option></select></label><label>나이<input id="ccAge" type="number" min="1" value="${d.age}"></label><label>키(cm)<input id="ccHeight" type="number" min="50" value="${d.height}"></label><label>체형<select id="ccBuild"><option>마른</option><option>보통</option><option>탄탄한</option><option>건장한</option><option>거대한</option></select></label></div><label>외형 특징<textarea id="ccAppearance" rows="4">${esc(d.appearance)}</textarea></label>${nav('‹ 이전',true)}`;if(step===2)body=`${progress}<h2>어떤 삶을 살아왔나요?</h2><div class="background-grid">${Object.entries(BACKGROUNDS).map(([id,x])=>`<button class="background-card ${d.background===id?'selected':''}" data-background="${id}"><b>${x.name}</b><span>시작 골드 ${x.gold} G</span><small>${Object.entries(x.mods).map(([k,v])=>`${STAT_INFO[k][0]} +${v}`).join(' · ')||'능력치 보정 없음'}</small></button>`).join('')}</div><label>추가 배경<textarea id="ccBackgroundNote" rows="4">${esc(d.backgroundNote)}</textarea></label>${nav('‹ 이전',!!d.background)}`;if(step===3){const left=pointsLeft(d);body=`${progress}<h2>어떤 재능을 타고났나요?</h2><p class="creator-hint">기본 5에서 12포인트를 배분합니다. 이 수치는 앞으로의 자동 성장 확률에도 사용됩니다.</p><div class="points-left">남은 포인트 <b>${left}</b> / 12</div><div class="stat-alloc">${STAT_KEYS.map(k=>`<div><span>${STAT_INFO[k][0]}</span><button data-minus="${k}" ${d.statAlloc[k]<=5?'disabled':''}>−</button><b>${d.statAlloc[k]}</b><button data-plus="${k}" ${left<=0||d.statAlloc[k]>=10?'disabled':''}>＋</button></div>`).join('')}</div><div class="random-actions"><button id="randomStats">🎲 무작위 배분</button><button id="resetStats">초기화</button></div>${nav('‹ 이전',left===0,'모험 시작')}`}homeOverlay(`<section class="creator-screen">${body}</section>`);bindCreator(step,d)}
function readBody(d){d.sex=$('#ccSex').value;d.age=Math.max(1,Number($('#ccAge').value)||20);d.height=Math.max(50,Number($('#ccHeight').value)||170);d.build=$('#ccBuild').value;d.appearance=$('#ccAppearance').value.trim()}
function bindCreator(step,d){if(step===0){$('#ccName').oninput=e=>{$('#creatorNext').disabled=!e.target.value.trim()};$('#creatorBack').onclick=showHome;$('#creatorNext').onclick=()=>{d.name=$('#ccName').value.trim();if(d.name)creator(1,d)}}if(step===1){$('#ccSex').value=d.sex;$('#ccBuild').value=d.build;$('#creatorBack').onclick=()=>{readBody(d);creator(0,d)};$('#creatorNext').onclick=()=>{readBody(d);creator(2,d)}}if(step===2){document.querySelectorAll('[data-background]').forEach(b=>b.onclick=()=>{d.backgroundNote=$('#ccBackgroundNote').value;d.background=b.dataset.background;creator(2,d)});$('#creatorBack').onclick=()=>{d.backgroundNote=$('#ccBackgroundNote').value;creator(1,d)};$('#creatorNext').onclick=()=>{d.backgroundNote=$('#ccBackgroundNote').value.trim();creator(3,d)}}if(step===3){const rerender=()=>creator(3,d);document.querySelectorAll('[data-minus]').forEach(b=>b.onclick=()=>{if(d.statAlloc[b.dataset.minus]>5)d.statAlloc[b.dataset.minus]--;rerender()});document.querySelectorAll('[data-plus]').forEach(b=>b.onclick=()=>{if(pointsLeft(d)>0&&d.statAlloc[b.dataset.plus]<10)d.statAlloc[b.dataset.plus]++;rerender()});$('#randomStats').onclick=()=>{d.statAlloc=Object.fromEntries(STAT_KEYS.map(k=>[k,5]));for(let i=0;i<12;i++){const keys=STAT_KEYS.filter(k=>d.statAlloc[k]<10),k=keys[Math.floor(Math.random()*keys.length)];d.statAlloc[k]++}rerender()};$('#resetStats').onclick=()=>{d.statAlloc=Object.fromEntries(STAT_KEYS.map(k=>[k,5]));rerender()};$('#creatorBack').onclick=()=>creator(2,d);$('#creatorNext').onclick=()=>finishCharacter(d)}}
function finishCharacter(d){if(pointsLeft(d)!==0||!d.background)return;const bg=BACKGROUNDS[d.background],stats={...d.statAlloc,mana:1,physicalDefense:0,magicDefense:0};for(const[k,v]of Object.entries(bg.mods))stats[k]+=v;state=clone(defaults);state.player={...state.player,name:d.name,appearance:d.appearance,title:'F급 모험가',stats:{...stats},initialStats:{...stats},growthProfile:{...d.statAlloc},statGrowth:{level:{},chronicle:{}},maxHp:100+Math.max(0,stats.vitality-5)*5,hp:100+Math.max(0,stats.vitality-5)*5,maxSp:100+Math.max(0,stats.vitality-5)*3,sp:100+Math.max(0,stats.vitality-5)*3,character:{created:true,createdAt:new Date().toISOString(),race:'human',raceName:'인간',sex:d.sex,age:d.age,height:d.height,build:d.build,appearance:d.appearance,background:d.background,backgroundName:bg.name,backgroundNote:d.backgroundNote},trait:{title:'',description:'',mastery:0,maxMastery:0}};state.gold=bg.gold;state.records=[{type:'origin',text:`인간으로 태어나 ${bg.name}의 삶을 살아왔다.${d.backgroundNote?' '+d.backgroundNote:''}`}];const start=fixedPlace({regionId:'capital',nodeId:'guild',locationId:'guild',name:'아르켈리온 길드',description:'의뢰·등록·정산과 탐사 정보가 집중되는 왕도 길드 본부.'});state.map.current={regionId:start.regionId,locationId:start.locationId,name:start.name,description:start.description};state.map.view='capital';activeSaveId=uid('character');save();queueCharacterRegistration(activeSaveId,state);retryPendingCharacterRegistrations();$('#homeOverlay').remove();render()}
