$('#saveImportInput').onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{const parsed=JSON.parse(await file.text()),incoming=parsed.state||parsed;if(!incoming?.player)throw 0;activeSaveId=uid('character');state=merge(clone(defaults),incoming);save();showHome()}catch{alert('올바른 TRPG Window 세이브 JSON이 아닙니다.')}};
async function submitChatMessage(){const input=$('#chatInput'),text=input.value.trim();if(!text||input.disabled)return;input.value='';try{await sendGeminiMessage(text)}catch(error){state.chatHistory=Array.isArray(state.chatHistory)?state.chatHistory:[];if(!state.chatHistory.some(message=>message.type==='player'&&message.text===text))state.chatHistory.push({id:uid('chat'),type:'player',text,createdAt:Date.now()});state.chatHistory.push({id:uid('chat'),type:'system',text:error?.message||'메시지를 전송하지 못했습니다.',createdAt:Date.now()});renderChat();$('#geminiStatus').textContent='전송 오류';$('#chatSend').disabled=input.disabled=false;input.focus()}}
$('#chatForm').onsubmit=e=>{e.preventDefault();submitChatMessage()};$('#chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();submitChatMessage()}};document.querySelectorAll('[data-mobile-view]').forEach(button=>button.onclick=()=>{const chat=!document.body.classList.contains('mobile-chat-visible');document.body.classList.toggle('mobile-chat-visible',chat);button.classList.toggle('active',chat);if(chat)requestAnimationFrame(()=>$('#chatInput').focus())});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.body.classList.remove('mobile-chat-visible');$('.mobile-chat-nav')?.classList.remove('active');openModal(b.dataset.tab)});$('#playerProfileButton').onclick=()=>{if(!activeSaveId)return alert('먼저 캐릭터를 생성하거나 불러와 주세요.');$('#modalBackdrop').classList.remove('hidden');openPortraitSetup('player')};$('#mapMenuBtn').onclick=()=>openModal('mapmenu');$('#closeModal').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target===$('#modalBackdrop'))closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
