syncMobileControls();addEventListener('resize',syncMobileControls);
$('#editBtn').onclick=()=>matchMedia('(max-width:760px)').matches?openModal('settings'):openGameStateTest();$('#editForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),old=state.player;state.player={...old,name:f.get('name').trim()||'이름 없음',level:Math.max(1,Math.min(MAX_LEVEL,+f.get('level')||1)),title:f.get('title').trim()||'모험가',exp:Math.max(0,+f.get('exp')||0),hp:Math.max(0,+f.get('hp')||0),maxHp:Math.max(1,+f.get('maxHp')||1),sp:Math.max(0,+f.get('sp')||0),maxSp:Math.max(1,+f.get('maxSp')||1)};state.location=f.get('location').trim()||'장소 미정';state.gold=Math.max(0,+f.get('gold')||0);state.day=Math.max(1,+f.get('day')||1);normalizeExperience();$('#editDialog').close();save()});
$('#grantTestWeapon').onclick=()=>{state.equipment.push(normalItem({id:uid('test_weapon'),name:'연습용 철검',description:'장비 흐름 검증을 위한 테스트 무기입니다.',grade:'희귀',slot:'주무기',stats:{strength:3,agility:1},testItem:true},'equipment'));save(false);alert('보유 장비에 연습용 철검을 지급했습니다.')};$('#grantTestEssence').onclick=()=>{state.essences.push(normalItem({id:uid('test_essence'),name:'메아리의 정수',description:'정수 슬롯과 스킬 파생 검증을 위한 테스트 정수입니다.',grade:'영웅',stats:{will:2,mana:1},activeSkills:[{name:'공명 파동',description:'응축한 공명을 방출합니다.'}],passiveSkills:[{name:'잔향',description:'의지와 마력의 흐름을 강화합니다.'}],testItem:true},'essence'));save(false);alert('보유 정수에 메아리의 정수를 지급했습니다.')};
function pickGrowth(level,point){const p=state.player,weights=STAT_KEYS.map(k=>Math.max(1,Number(p.growthProfile?.[k])||1)),total=weights.reduce((a,b)=>a+b,0);let cursor=((level*17+point*31)%1000)/1000*total;for(let i=0;i<STAT_KEYS.length;i++){cursor-=weights[i];if(cursor<0)return STAT_KEYS[i]}return STAT_KEYS[0]}
function growBase(level){const p=state.player;p.statGrowth??={level:{},chronicle:{}};for(let point=0;point<2;point++){const k=pickGrowth(level,point);p.stats[k]=(Number(p.stats[k])||0)+1;p.statGrowth.level[k]=(p.statGrowth.level[k]||0)+1}if(level%5===0)for(const k of STAT_KEYS){p.stats[k]=(Number(p.stats[k])||0)+1;p.statGrowth.level[k]=(p.statGrowth.level[k]||0)+1}}
function normalizeExperience(){const p=state.player;p.level=Math.max(1,Math.min(MAX_LEVEL,Number(p.level)||1));p.exp=Math.max(0,Number(p.exp)||0);p.levelHistory=Array.isArray(p.levelHistory)?p.levelHistory:[];while(p.level<MAX_LEVEL&&p.exp>=expRequired(p.level)){p.exp-=expRequired(p.level);p.level++;growBase(p.level);p.levelHistory.push({level:p.level,at:Date.now()})}if(p.level>=MAX_LEVEL)p.exp=0;return p.level}
function inferredRegion(payload={}){const aliases=Array.isArray(payload.aliases)?payload.aliases:[payload.aliases],text=[payload.regionId,payload.nodeId,payload.locationId,payload.name,...aliases].filter(Boolean).join(' ').toLowerCase();if(/대던전|던전\s*입구|great.?dungeon|dungeon/.test(text))return'dungeon';if(/북부|산악|칼드렌|north|mountain/.test(text))return'northlands';if(/서남|강변|river/.test(text))return'riverlands';if(/남부|해안|항구|세르반|south|coast|port/.test(text))return'southcoast';if(/동부|삼림|숲|에르바스|east|forest/.test(text))return'eastforest';if(/왕도|아르켈리온|왕성구|마탑|길드|천린구|대시장|철화구|야월구|녹영구|capital/.test(text))return'capital';return payload.regionId||'capital'}
function fixedPlace(payload={}){const regionId=inferredRegion(payload),locationId=String(payload.locationId||payload.name||uid('place')).trim().toLowerCase().replace(/\s+/g,'_'),mapView=payload.mapView||(regionId==='capital'?'capital':regionId==='dungeon'?'dungeon':'continent'),existing=state.map.places[locationId],isDungeonEntrance=regionId==='dungeon'&&/입구|entrance/.test([payload.locationId,payload.name].filter(Boolean).join(' ').toLowerCase());if(existing){const wasWrong=existing.regionId!==regionId||existing.mapView!==mapView;existing.regionId=regionId;existing.mapView=mapView;existing.name=payload.name||existing.name;existing.description=payload.description||existing.description;if(wasWrong&&isDungeonEntrance){existing.x=50;existing.y=10}return existing}const nodes=mapView==='capital'?CAPITAL_NODES:MAP_REGIONS,center=isDungeonEntrance?{x:50,y:10}:nodes.find(n=>n.id===payload.nodeId||n.id===regionId||n.locationId===regionId)||{x:50,y:50},spread=isDungeonEntrance?0:mapView==='capital'?5:8,x=Math.max(7,Math.min(93,center.x+(Math.random()-.5)*spread*2)),y=Math.max(8,Math.min(92,center.y+(Math.random()-.5)*spread*2)),place={locationId,regionId,mapView,x:Math.round(x*100)/100,y:Math.round(y*100)/100,name:payload.name||locationId,description:payload.description||'',aliases:payload.aliases||[],createdAt:Date.now()};state.map.places[locationId]=place;return place}
function processedCommandIds(){try{return new Set(JSON.parse(localStorage.getItem(SYNC_IDS_KEY)||'[]'))}catch{return new Set()}}
function rememberCommand(id){const ids=processedCommandIds();ids.add(id);localStorage.setItem(SYNC_IDS_KEY,JSON.stringify([...ids].slice(-500)))}
async function sheetCommandRequest(action,details={}){const config=sheetWriterConfig(),url=config.sheetWriteUrl?.trim(),token=config.sheetWriteToken?.trim();if(!url||!token)throw new Error('Apps Script 시트 명령 연결이 설정되지 않았습니다.');const controller=new AbortController(),timeoutMs=['geminiChat','openContainer'].includes(action)?60000:12000,timer=setTimeout(()=>controller.abort(),timeoutMs);try{const response=await fetch(url,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,token,spreadsheetId:SHEET_SYNC.sheetId,sheetName:SHEET_SYNC.sheetName,...details}),signal:controller.signal});if(!response.ok)throw new Error(`시트 응답 오류 ${response.status}`);const result=await response.json();if(!result.ok)throw new Error(result.error||'시트 명령 요청 실패');return result}catch(error){if(error?.name==='AbortError')throw new Error('Gemini 응답 시간이 초과되었습니다. 잠시 후 다시 시도해 주세요.');throw error}finally{clearTimeout(timer)}}
function publicSheetRows(){return new Promise((resolve,reject)=>{const callback=`trpgSheet_${Date.now()}_${Math.random().toString(36).slice(2)}`,script=document.createElement('script'),timeout=setTimeout(()=>finish(new Error('시트 응답 시간 초과')),12000);function finish(error,value){clearTimeout(timeout);delete window[callback];script.remove();error?reject(error):resolve(value)}window[callback]=response=>{if(response?.status==='error')return finish(new Error(response.errors?.[0]?.message||'시트를 읽을 수 없습니다.'));const table=response?.table||{},headers=(table.cols||[]).map((c,i)=>c.label||`column_${i}`),rows=(table.rows||[]).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r.c?.[i]?.v??''])));finish(null,rows)};script.onerror=()=>finish(new Error('시트가 공개되어 있지 않습니다. 설정에서 Apps Script 시트 명령 연결을 저장해 주세요.'));script.src=`https://docs.google.com/spreadsheets/d/${SHEET_SYNC.sheetId}/gviz/tq?sheet=${encodeURIComponent(SHEET_SYNC.sheetName)}&headers=1&tqx=out:json;responseHandler:${callback}`;document.head.appendChild(script)})}
async function sheetRows(){const config=sheetWriterConfig();if(config.sheetWriteUrl&&config.sheetWriteToken){const result=await sheetCommandRequest('readPendingCommands',{activeSaveId});return Array.isArray(result.commands)?result.commands:[]}return publicSheetRows()}
async function updateSheetCommandStatus(commandId,status,result={}){const config=sheetWriterConfig();if(!config.sheetWriteUrl||!config.sheetWriteToken)return false;await sheetCommandRequest('updateCommandStatus',{commandId,status,result,processedAt:['applied','failed'].includes(status)?new Date().toISOString():''});return true}
