function commandTargetSave(command,payload={}){const explicit=String(payload.targetSaveId||payload.target_save_id||'').trim();if(explicit)return explicit;const column=String(command.character_id||'').trim(),type=String(command.command_type||'').trim().toLowerCase();if(['upsert_character','update_character','character'].includes(type)&&column===String(payload.id||'').trim())return'';return /^character_[a-z0-9_]+$/i.test(column)?column:''}
function applySheetCommand(command){const payload=parseCommandPayload(command.payload_json),api=window.TRPGWindow,type=String(command.command_type||'').trim().toLowerCase();switch(type){case'set_location':case'location':return api.setLocation(payload);case'upsert_character':case'update_character':case'character':return api.upsertCharacter(payload);case'set_speakers':state.speakers=clone(Array.isArray(payload)?payload:payload.speakers||[]);state.activeSpeakerId=Array.isArray(payload)?'':payload.activeSpeakerId||'';return save();case'grant_equipment':case'equipment':return api.grantEquipment(grantPayload(payload,'grant_equipment'));case'grant_essence':case'essence':return api.grantEssence(grantPayload(payload,'grant_essence'));case'remove_equipped_essence':return api.removeEquippedEssence(payload.id);case'grant_inventory':case'inventory':{const item=grantPayload(payload,'grant_inventory');return api.grantInventory(item,item.quantity||payload.quantity||1)}case'remove_inventory':return api.removeInventory(payload.id,payload.quantity||1);case'award_experience':case'exp':return api.awardExperience(payload.amount??payload.exp??0);case'grant_gold':case'gold':return api.grantGold(payload.amount??payload.gold??0);case'increase_stats':case'stats':return api.increaseStats(payload.stats||payload,payload.source||'chronicle');case'increase_special_stats':case'special_stats':return api.increaseSpecialStats(payload.stats||payload);case'set_trait':case'trait':return api.setTrait(payload);case'set_state':return api.setState(payload);default:throw new Error(`지원하지 않는 명령: ${type||'(비어 있음)'}`)}}
