async function sendGeminiMessage(text){const status=$('#geminiStatus'),send=$('#chatSend'),input=$('#chatInput'),memory=ensureGmContext();memory.playerTurns=(Number(memory.playerTurns)||0)+1;const summaryDue=memory.playerTurns-(Number(memory.lastSummaryTurn)||0)>=6||importantMemoryTurn(text),fullRulesDue=memory.playerTurns===1||memory.playerTurns-(Number(memory.lastFullRulesTurn)||0)>=24;state.chatHistory=Array.isArray(state.chatHistory)?state.chatHistory:[];state.chatHistory.push({id:uid('chat'),type:'player',text,createdAt:Date.now()});state.chatHistory=state.chatHistory.slice(-200);save(false);renderChat();status.textContent='GM이 장면을 구성하는 중';send.disabled=input.disabled=true;try{if(!activeSaveId)throw new Error('먼저 플레이할 캐릭터를 선택해 주세요.');const result=await sheetCommandRequest('geminiChat',{activeSaveId,message:text,gameState:geminiStateSnapshot(),history:state.chatHistory.slice(-10).map(({type,speakerId,speakerName,text,action})=>({type,speakerId,speakerName,text,action})),longMemory:memory.longMemory,summaryDue,fullRulesDue,gmRules:state.settings.gmRules||'',sheetRules:state.settings.sheetRules||''}),commands=Array.isArray(result.commands)?result.commands:[];for(const command of commands)try{applySheetCommand({command_type:command.command_type||command.type,payload_json:command.payload_json??command.payload??{}})}catch(error){state.chatHistory.push({id:uid('chat'),type:'system',text:`명령 적용 실패: ${error.message}`,createdAt:Date.now()})}const messages=Array.isArray(result.messages)?result.messages:result.message?[{type:'gm',text:result.message}]:[];for(const message of messages)state.chatHistory.push({id:uid('chat'),type:message.type||'gm',speakerId:message.speakerId||message.speaker_id||'',speakerName:message.speakerName||message.speaker_name||'',text:message.text||'',action:message.action||'',createdAt:Date.now()});if(result.memoryUpdate&&typeof result.memoryUpdate==='object'){memory.longMemory={...memory.longMemory,...clone(result.memoryUpdate)};memory.lastSummaryTurn=memory.playerTurns}if(fullRulesDue)memory.lastFullRulesTurn=memory.playerTurns;state.chatHistory=state.chatHistory.slice(-200);save();status.textContent='응답 완료'}catch(error){state.chatHistory=Array.isArray(state.chatHistory)?state.chatHistory:[];state.chatHistory.push({id:uid('chat'),type:'system',text:error?.message||'Gemini 연결에 실패했습니다.',createdAt:Date.now()});state.chatHistory=state.chatHistory.slice(-200);save();status.textContent='연결 오류'}finally{send.disabled=input.disabled=false;input.focus()}}
